+package diff
+
+import (
+	"strings"
+	"testing"
+
+	"github.com/immuta/operations/apps/birdseye/internal/archive"
+)
+
+func mkArchive(files map[string]string) archive.Module {
+	out := archive.Module{Files: make(map[string][]byte, len(files))}
+	for k, v := range files {
+		out.Files[k] = []byte(v)
+	}
+	return out
+}
+
+func findFile(t *testing.T, ds []FileDiff, path string) FileDiff {
+	t.Helper()
+	for _, d := range ds {
+		if d.Path == path {
+			return d
+		}
+	}
+	t.Fatalf("no FileDiff for %s; got %d entries", path, len(ds))
+	return FileDiff{}
+}
+
+func TestTextualAdded(t *testing.T) {
+	a := mkArchive(nil)
+	b := mkArchive(map[string]string{"new.tf": "x\n"})
+	ds := Textual(a, b)
+	d := findFile(t, ds, "new.tf")
+	if d.Status != StatusAdded {
+		t.Errorf("status = %v, want Added", d.Status)
+	}
+	if d.Adds != 1 || d.Dels != 0 {
+		t.Errorf("adds/dels = %d/%d", d.Adds, d.Dels)
+	}
+}
+
+func TestTextualRemoved(t *testing.T) {
+	a := mkArchive(map[string]string{"old.tf": "x\n"})
+	b := mkArchive(nil)
+	ds := Textual(a, b)
+	d := findFile(t, ds, "old.tf")
+	if d.Status != StatusRemoved {
+		t.Errorf("status = %v, want Removed", d.Status)
+	}
+	if d.Adds != 0 || d.Dels != 1 {
+		t.Errorf("adds/dels = %d/%d", d.Adds, d.Dels)
+	}
+}
+
+func TestTextualModified(t *testing.T) {
+	a := mkArchive(map[string]string{"m.tf": "alpha\nbeta\n"})
+	b := mkArchive(map[string]string{"m.tf": "alpha\nGAMMA\n"})
+	ds := Textual(a, b)
+	d := findFile(t, ds, "m.tf")
+	if d.Status != StatusModified {
+		t.Errorf("status = %v, want Modified", d.Status)
+	}
+	if !strings.Contains(d.Unified, "-beta") || !strings.Contains(d.Unified, "+GAMMA") {
+		t.Errorf("unified missing expected lines:\n%s", d.Unified)
+	}
+}
+
+func TestTextualIdenticalReturnsEmpty(t *testing.T) {
+	a := mkArchive(map[string]string{"m.tf": "x\n"})
+	b := mkArchive(map[string]string{"m.tf": "x\n"})
+	if got := Textual(a, b); len(got) != 0 {
+		t.Errorf("expected 0 diffs, got %d", len(got))
+	}
+}
+
+func TestTextualSortedByPath(t *testing.T) {
+	a := mkArchive(map[string]string{"z.tf": "a\n", "a.tf": "a\n"})
+	b := mkArchive(map[string]string{"z.tf": "b\n", "a.tf": "b\n"})
+	ds := Textual(a, b)
+	if len(ds) != 2 {
+		t.Fatalf("got %d diffs, want 2", len(ds))
+	}
+	if ds[0].Path != "a.tf" || ds[1].Path != "z.tf" {
+		t.Errorf("expected sorted by path; got %s, %s", ds[0].Path, ds[1].Path)
+	}
+}
