+// Package diff produces FileDiff entries and optional SemanticChange
+// entries from a pair of extracted Modules. All functions are pure: no
+// I/O, no globals.
+package diff
+
+// FileStatus describes what happened to a file between the two versions.
+type FileStatus int
+
+const (
+	StatusModified FileStatus = iota
+	StatusAdded
+	StatusRemoved
+)
+
+func (s FileStatus) String() string {
+	switch s {
+	case StatusAdded:
+		return "added"
+	case StatusRemoved:
+		return "removed"
+	default:
+		return "modified"
+	}
+}
+
+// FileDiff is a per-file diff result. Unified holds the rendered diff
+// hunks; Adds/Dels are the count of added/removed lines for summary
+// rendering.
+type FileDiff struct {
+	Path    string
+	Status  FileStatus
+	Unified string
+	Adds    int
+	Dels    int
+}
+
+// SemanticChange is a single HCL-aware change. Kind is one of "resource",
+// "variable", "output", "provider", "locals", "data", or "module".
+type SemanticChange struct {
+	Kind   string
+	Name   string
+	Status FileStatus
+	Detail string
+}
+
+// Result is what cmd/diff renders. Semantic is nil unless --semantic was
+// requested.
+type Result struct {
+	Files    []FileDiff
+	Semantic []SemanticChange
+}

